            handle.seek(0, os.SEEK_END)
            size = handle.tell()
            if size == 0:
                return
            handle.seek(max(0, size - 4096))
            tail = handle.read()
    except FileNotFoundError:
        return
    except OSError:
        # Unreadable log: let replay mark it invalid.
        return
    if tail.endswith(b"\n"):
        return
